ui.css:
.hud-bar { position: relative; height: 22px; background: rgba(245,238,222,.62); border: 1.5px solid rgba(42,27,20,.9); border-radius: 255px 18px 225px 18px / 18px 225px 18px 255px; }
.hud-bar > .fill { height: 100%; background: linear-gradient(90deg, #c23b2b, #d8483a 40%, #9a2418); filter: url(#wash); }
.hud-text { font: 400 19px 'IM Fell English SC', Georgia, serif; color: #2a1b14; text-shadow: 0 0 3px #f5eede, 0 0 7px #f5eede, 0 0 12px rgba(245,238,222,.8); }
.hud-label { font: 700 20px 'Caveat', 'Segoe Print', cursive; color: #8a3a1e; }
.panel { background: #f5eede; color: #2a1b14; border: 1.5px solid rgba(42,27,20,.85); border-radius: 255px 18px 225px 18px / 18px 225px 18px 255px; box-shadow: 0 3px 12px rgba(60,40,20,.3); }
.card { background: #f5eede; filter: drop-shadow(0 8px 10px rgba(30,18,8,.45)); transform: rotate(-1.4deg); }
